#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#define MAX_FIRMWARE_SIZE (16 * 1024 * 1024)
#define ALLOWED_SUBNET "192.168.1.0"
#define ALLOWED_MASK 0xFFFFFF00
#define UPDATE_PORT 8443

typedef struct {
    char manifest_url[512];
    char checksum[65];
    uint32_t firmware_size;
    uint8_t flags;
} update_request_t;

typedef struct {
    struct in_addr resolved_addr;
    time_t resolve_time;
    int validated;
} dns_cache_entry_t;

static dns_cache_entry_t g_dns_cache = {0};

/* Resolve hostname and check if it's on the allowed internal network */
static int validate_update_source(const char *hostname) {
    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        uint32_t addr = ntohl(ipv4->sin_addr.s_addr);
        uint32_t subnet = ntohl(inet_addr(ALLOWED_SUBNET));

        if ((addr & ALLOWED_MASK) == (subnet & ALLOWED_MASK)) {
            /* Cache the validated address for later use */
            g_dns_cache.resolved_addr = ipv4->sin_addr;
            g_dns_cache.resolve_time = time(NULL);
            g_dns_cache.validated = 1;
            freeaddrinfo(res);
            return 0;
        }
    }

    freeaddrinfo(res);
    fprintf(stderr, "Source not on allowed subnet\n");
    return -1;
}

/* Bounded search for a needle within exactly 'hlen' bytes of haystack.
 * Avoids reading past the received data (unlike strstr on non-terminated buffers). */
static char *find_bytes(char *haystack, size_t hlen, const char *needle, size_t nlen) {
    if (nlen == 0 || hlen < nlen) return NULL;
    for (size_t i = 0; i + nlen <= hlen; i++) {
        if (memcmp(haystack + i, needle, nlen) == 0) {
            return haystack + i;
        }
    }
    return NULL;
}

/* Fetch firmware using the previously validated and cached IP address */
static int fetch_firmware(const char *hostname, const char *path, uint8_t *buf, size_t max_len) {
    /* Use the cached validated address instead of re-resolving */
    if (!g_dns_cache.validated) {
        fprintf(stderr, "No validated address in cache\n");
        return -1;
    }

    /* Verify cache freshness - must be within 2 seconds */
    if (time(NULL) - g_dns_cache.resolve_time > 2) {
        fprintf(stderr, "DNS cache expired\n");
        g_dns_cache.validated = 0;
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UPDATE_PORT);
    server_addr.sin_addr = g_dns_cache.resolved_addr;

    /* Double-check the cached address is still on allowed subnet */
    uint32_t addr = ntohl(g_dns_cache.resolved_addr.s_addr);
    uint32_t subnet = ntohl(inet_addr(ALLOWED_SUBNET));
    if ((addr & ALLOWED_MASK) != (subnet & ALLOWED_MASK)) {
        fprintf(stderr, "Cached address no longer valid\n");
        g_dns_cache.validated = 0;
        return -1;
    }

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        return -1;
    }

    struct timeval tv = {.tv_sec = 5, .tv_usec = 0};
    setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        close(sockfd);
        return -1;
    }

    /* Verify connected peer address matches our validated address */
    struct sockaddr_in peer_addr;
    socklen_t peer_len = sizeof(peer_addr);
    if (getpeername(sockfd, (struct sockaddr *)&peer_addr, &peer_len) < 0) {
        close(sockfd);
        return -1;
    }
    if (peer_addr.sin_addr.s_addr != g_dns_cache.resolved_addr.s_addr) {
        close(sockfd);
        return -1;
    }

    /* Send HTTP GET request */
    char request[1024];
    int req_len = snprintf(request, sizeof(request),
        "GET %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n",
        path, hostname);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        close(sockfd);
        return -1;
    }

    if (send(sockfd, request, req_len, 0) < 0) {
        close(sockfd);
        return -1;
    }

    /* Read response body (skip headers) */
    size_t total = 0;
    char tmp[4096];
    int header_done = 0;
    ssize_t n;

    while ((n = recv(sockfd, tmp, sizeof(tmp), 0)) > 0) {
        size_t nbytes = (size_t)n;
        if (!header_done) {
            /* Bounded search over exactly nbytes to avoid OOB read */
            char *body = find_bytes(tmp, nbytes, "\r\n\r\n", 4);
            if (body) {
                body += 4;
                header_done = 1;
                size_t body_len = nbytes - (size_t)(body - tmp);
                if (total + body_len > max_len) break;
                memcpy(buf + total, body, body_len);
                total += body_len;
            }
        } else {
            if (total + nbytes > max_len) break;
            memcpy(buf + total, tmp, nbytes);
            total += nbytes;
        }
    }

    close(sockfd);
    return (int)total;
}

/* Parse URL into hostname and path components */
static int parse_url(const char *url, char *hostname, size_t hlen, char *path, size_t plen) {
    const char *start = url;
    if (strncmp(url, "http://", 7) == 0) start += 7;
    else if (strncmp(url, "https://", 8) == 0) start += 8;
    else return -1;

    const char *slash = strchr(start, '/');
    if (!slash) {
        strncpy(hostname, start, hlen - 1);
        hostname[hlen - 1] = '\0';
        strncpy(path, "/", plen - 1);
        path[plen - 1] = '\0';
    } else {
        size_t host_len = slash - start;
        if (host_len >= hlen) return -1;
        memcpy(hostname, start, host_len);
        hostname[host_len] = '\0';
        strncpy(path, slash, plen - 1);
        path[plen - 1] = '\0';
    }
    return 0;
}

int process_firmware_update(const update_request_t *req) {
    if (!req || req->firmware_size > MAX_FIRMWARE_SIZE || req->firmware_size == 0) {
        return -1;
    }

    char hostname[256], path[512];
    if (parse_url(req->manifest_url, hostname, sizeof(hostname), path, sizeof(path)) < 0) {
        fprintf(stderr, "Invalid URL format\n");
        return -1;
    }

    /* Step 1: Validate that the source is on our trusted internal network */
    if (validate_update_source(hostname) < 0) {
        fprintf(stderr, "Update source validation failed\n");
        return -1;
    }

    /* Step 2: Small delay for rate limiting (anti-DoS) */
    usleep(100000);

    /* Step 3: Fetch the firmware using cached validated IP */
    uint8_t *firmware_buf = malloc(req->firmware_size);
    if (!firmware_buf) return -1;

    int received = fetch_firmware(hostname, path, firmware_buf, req->firmware_size);
    if (received <= 0) {
        free(firmware_buf);
        return -1;
    }

    /* Step 4: Apply firmware (simplified) */
    printf("Firmware update applied: %d bytes from %s\n", received, hostname);
    free(firmware_buf);
    return 0;
}

int main(int argc, char *argv[]) {
    /* Simulate receiving an update request from user input */
    update_request_t req;
    memset(&req, 0, sizeof(req));

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <manifest_url>\n", argv[0]);
        return 1;
    }

    strncpy(req.manifest_url, argv[1], sizeof(req.manifest_url) - 1);
    req.firmware_size = MAX_FIRMWARE_SIZE;
    req.flags = 0;

    return process_firmware_update(&req);
}
